import logging
import queue
import threading

log = logging.getLogger(__name__)


class QueueWorker:
    """Consume items from a queue on a background thread."""

    _SHUTDOWN = object()

    def __init__(self, callback, work_queue=None, name="queue-worker"):
        self._callback = callback
        self.queue = work_queue if work_queue is not None else queue.Queue()
        self._thread = threading.Thread(target=self._run, name=name, daemon=True)
        self._started = False

    def start(self):
        if self._started:
            raise RuntimeError("worker already started")
        self._started = True
        self._thread.start()

    def submit(self, item):
        self.queue.put(item)

    def _run(self):
        while True:
            item = self.queue.get()
            try:
                if item is self._SHUTDOWN:
                    return
                self._callback(item)
            except Exception:
                log.exception("callback failed for item %r", item)
            finally:
                self.queue.task_done()

    def join_pending(self):
        """Block until every submitted item has been processed."""
        self.queue.join()

    def stop(self, timeout=None):
        """Finish the queued items, then shut the thread down."""
        if not self._started:
            return
        self.queue.put(self._SHUTDOWN)
        self._thread.join(timeout)
        if self._thread.is_alive():
            log.warning("worker thread did not exit within %s seconds", timeout)
        self._started = False

    def __enter__(self):
        self.start()
        return self

    def __exit__(self, exc_type, exc, tb):
        self.stop()
        return False
